    if h.sum() <= 0:
        h = np.ones(50)

    best = h.copy()
    bestC = _C(best)

    N = h.size
    # Try several N values, coarse-to-fine, using a reshaping trick:
    # larger N gives finer resolution; the optimal f is roughly a smooth bump.
    # Strategy: for a given N, do coordinate/multiplicative updates reducing max convolution
    # via local perturbations. Use random restarts around the current best.
    rng = np.random.default_rng(12345)

    def refine(h, deadline):
        h = h.copy()
        N = h.size
        C = _C(h)
        # Iterative single-coordinate multiplicative perturbation search.
        # np.convolve is O(N^2); keep N modest but try to grow.
        step = 0.1
        stall = 0
        while time.process_time() < deadline:
            improved = False
            idx = rng.permutation(N)
            for i in idx:
                if time.process_time() >= deadline:
                    break
                old = h[i]
                for fac in (1.0 + step, 1.0 - step, 1.0 + 2*step, 1.0 - 2*step):
                    h[i] = old * fac if old > 0 else (fac - 1.0) * step
                    if h[i] < 0:
                        h[i] = 0.0
                    if h.sum() <= 0:
                        h[i] = old
                        continue
                    Cn = _C(h)
                    if Cn < C - 1e-12:
                        C = Cn
                        improved = True
                        break
                    else:
                        h[i] = old
            if not improved:
                stall += 1
                step *= 0.5
                if step < 1e-6 or stall > 8:
                    break
            else:
                stall = 0
        return h, C

    # Try to increase resolution: the theoretical optimum is smooth, so larger N helps.
    candidates = []
    for Ntry in [50, 100, 200, 400, 800, 1600, 3200, 6400, 12800, 30000]:
        if Ntry < N:
            continue
        candidates.append(Ntry)
        if time.process_time() > t0 + budget * 0.3:
            break
    if not candidates:
        candidates = [N]

    # Seed with current best resampled to each candidate N.
    for Ntry in candidates:
        if time.process_time() > t0 + budget:
            break
        # resample best to Ntry via linear interpolation of cumulative mass
        if Ntry == best.size:
            seed = best.copy()
        else:
            x_old = (np.arange(best.size) + 0.5) / best.size
            x_new = (np.arange(Ntry) + 0.5) / Ntry
            seed = np.interp(x_new, x_old, best)
        seed = np.maximum(seed, 0)
