        seed *= Ntry / seed.sum()
        # allocate remaining time proportionally; do a quick refine
        remaining = budget - (time.process_time() - t0)
        per = remaining / max(1, (len(candidates) - candidates.index(Ntry)))
        deadline = time.process_time() + per
        sh, sC = refine(seed, deadline)
