            best, bestC = sh, sC

    # Final polish on best within remaining time.
    remaining = budget - (time.process_time() - t0)
    if remaining > 0.2:
        deadline = time.process_time() + remaining
        bh, bC = refine(best, deadline)
        if bC < bestC:
            best, bestC = bh, bC

    # Ensure validity.
    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(50)
    return best

