import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_fft(h):
    # C via FFT convolution; h assumed non-negative, sum normalized internally
    s = h.sum()
    if s <= 0:
        return np.inf
    N = len(h)
    n = 1
    while n < 2 * N - 1:
        n *= 2
    H = np.fft.rfft(h, n)
    conv = np.fft.irfft(H * H, n)[:2 * N - 1]
    return 2.0 * N * np.max(conv) / (s * s)


def _expand(ctrl, N):
    M = len(ctrl)
    x_old = (np.arange(M) + 0.5) / M
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, ctrl)


def _resample(h, N):
    M = len(h)
    if M == N:
        return h.copy()
    x_old = (np.arange(M) + 0.5) / M
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def _fit(ctrl0, N, deadline):
    M = len(ctrl0)

    def obj(c):
        c = np.maximum(c, 0.0)
        s = c.sum()
        if s <= 0:
            return 1e9
        h = _expand(c / s, N)
        return _C_fft(h)

    res = minimize(obj, ctrl0, method='L-BFGS-B',
                   bounds=[(0.0, None)] * M,
                   options={'maxiter': 500, 'maxfun': 20000, 'ftol': 1e-12, 'gtol': 1e-10})
    return np.maximum(res.x, 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds - 1.5

    N = 4096
    M = 32

    # Build candidate control-point seeds.
    seeds = []
    if start is not None:
        h0 = np.asarray(start, dtype=float).copy()
        if h0.ndim == 1 and h0.size > 0 and np.all(np.isfinite(h0)) and h0.sum() > 0:
            h0 = np.maximum(h0, 0.0)
            h0r = _resample(h0, N)
            # control points from resampled start
            x_new = (np.arange(M) + 0.5) / M
            x_old = (np.arange(N) + 0.5) / N
            seeds.append(np.interp(x_new, x_old, h0r))
    # cosine bump seed
    t = (np.arange(M) + 0.5) / M
    seeds.append(np.cos(np.pi * (t - 0.5)) ** 2 + 1e-3)
    # flat seed
    seeds.append(np.ones(M))

    best_h = None
    bestC = np.inf

    # Evaluate each seed directly (expanded) first.
    for c in seeds:
        c = np.maximum(c, 0.0)
        if c.sum() <= 0:
            continue
        h = _expand(c / c.sum(), N)
        Cv = _C_fft(h)
        if Cv < bestC:
            bestC = Cv
            best_h = h.copy()

    # Optimize each seed with L-BFGS-B, splitting remaining time.
    n_seeds = len(seeds)
    for k, c in enumerate(seeds):
        if time.process_time() > t0 + budget:
            break
        remaining = budget - (time.process_time() - t0)
        per = remaining / max(1, n_seeds - k)
        deadline = time.process_time() + per
        c = np.maximum(c, 0.0)
        if c.sum() <= 0:
            continue
        c = c / c.sum()
        try:
            copt = _fit(c, N, deadline)
        except Exception:
            continue
        if copt.sum() <= 0:
            continue
        h = _expand(copt / copt.sum(), N)
        Cv = _C_fft(h)
        if Cv < bestC:
            bestC = Cv
            best_h = h.copy()

    if best_h is None:
        best_h = np.ones(N)

    best_h = np.maximum(best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(N)
    return best_h

