        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_fft(h):
    # exact same value as _C but via FFT for speed on large N
    s = h.sum()
    if s <= 0:
        return np.inf
    N = len(h)
    n = 1
    while n < 2 * N:
        n *= 2
    f = np.fft.rfft(h, n)
    conv = np.fft.irfft(f * f, n)[:2 * N - 1]
    return 2.0 * N * np.max(conv) / (s * s)


def _polish(h, deadline, rng):
    """Incremental coordinate multiplicative polish (from experiment 1)."""
    h = h.copy()
    N = h.size
    C = _C_fft(h)
    step = 0.1
    stall = 0
    while time.process_time() < deadline:
        improved = False
        idx = rng.permutation(N)
        for i in idx:
            if time.process_time() >= deadline:
                break
            old = h[i]
            for fac in (1.0 + step, 1.0 - step, 1.0 + 2 * step, 1.0 - 2 * step):
                h[i] = old * fac if old > 0 else (fac - 1.0) * step
                if h[i] < 0:
                    h[i] = 0.0
                if h.sum() <= 0:
                    h[i] = old
                    continue
                Cn = _C_fft(h)
                if Cn < C - 1e-12:
                    C = Cn
                    improved = True
                    break
                else:
                    h[i] = old
        if not improved:
            stall += 1
            step *= 0.5
            if step < 1e-6 or stall > 8:
                break
        else:
            stall = 0
    return h, C


