    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_fft(h, L=None):
    N = len(h)
    s = h.sum()
    if s <= 0:
        return np.inf
    if L is None:
        L = 1
        while L < 2 * N:
            L *= 2
    H = np.fft.rfft(h, L)
    conv = np.fft.irfft(H * np.conj(H), L)[:2 * N - 1]
    return 2.0 * N * np.max(conv) / (s * s)


def _resample(h, Nnew):
    if h.size == Nnew:
        return h.copy()
    x_old = (np.arange(h.size) + 0.5) / h.size
    x_new = (np.arange(Nnew) + 0.5) / Nnew
    out = np.interp(x_new, x_old, h)
    out = np.maximum(out, 0.0)
    s = out.sum()
    if s <= 0:
        return np.ones(Nnew)
    return out / s


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    N = 30000

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size == 0 or not np.all(np.isfinite(s)) or s.sum() <= 0:
            s = None
    else:
        s = None

    if s is None:
        h = np.ones(N)
    else:
        s = np.maximum(s, 0.0)
        h = _resample(s, N)
    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        h = np.ones(N)
    h = h / h.sum()

    L = 1
    while L < 2 * N:
        L *= 2

    best = h.copy()
    bestC = _C_fft(best, L)

    # Precompute index helpers for gradient assembly (avoid per-knot arange).
    def eg_step(h, eta, k_top, band_frac):
        H = np.fft.rfft(h, L)
        conv = np.fft.irfft(H * np.conj(H), L)[:2 * N - 1]
        cmax = conv.max()
        # Take the top-k distinct knots near the max.
        idx = np.argpartition(conv, -k_top)[-k_top:]
        grad = np.zeros(N)
        for t in idx:
            jlo = max(0, t - (N - 1))
            jhi = min(N - 1, t)
            if jhi >= jlo:
                # h[t-j] for j in [jlo, jhi]
                grad[jlo:jhi + 1] += 2.0 * h[t - np.arange(jlo, jhi + 1)]
        gm = np.max(np.abs(grad))
        if gm < 1e-14:
            return h, False, conv
        hn = h * np.exp(-eta * grad / gm)
        ssum = hn.sum()
        if ssum <= 0 or not np.isfinite(ssum):
            return h, False, conv
        return hn / ssum, True, conv

    def optimize(h, t_end, k_top=6):
        h = h.copy()
        C = _C_fft(h, L)
        besth, bestCc = h.copy(), C
        eta0, eta1 = 0.5, 0.004
        tstart = time.process_time()
        span = max(t_end - tstart, 1e-9)
        it = 0
        while True:
            now = time.process_time()
            if now >= t_end:
                break
            frac = min(max((now - tstart) / span, 0.0), 1.0)
            eta = eta0 * (eta1 / eta0) ** frac
            h, ok, conv = eg_step(h, eta, k_top, 0.0)
            if not ok:
                break
            it += 1
            if it % 25 == 0:
                C = _C_fft(h, L)
                if C < bestCc:
                    bestCc = C
                    besth = h.copy()
        C = _C_fft(h, L)
        if C < bestCc:
            bestCc = C
            besth = h.copy()
        return besth, bestCc

    # Phase 1: polish start at full N.
    frac1 = 0.55
    t_phase1 = min(deadline, t0 + (deadline - t0) * frac1)
    h1, c1 = optimize(best, t_phase1)
    if c1 < bestC:
        best, bestC = h1, c1

    # Phase 2: try a couple of coarser resolutions; the optimum at finite N
    # may be slightly better represented at moderate N, then resample back.
    for Ntry in [8192, 4096, 16384]:
        if time.process_time() >= deadline - 0.5:
            break
        seed = _resample(best, Ntry)
        # Temporarily switch N by wrapping (use local closures at Ntry).
        # Simpler: run optimize at current N but seed from resampled+upsampled.
        seed30 = _resample(seed, N)
        remaining = deadline - time.process_time()
        if remaining <= 0.3:
            break
        t_end = time.process_time() + remaining * 0.35
        hn, cn = optimize(seed30, t_end)
        if cn < bestC:
            best, bestC = hn, cn

    # Phase 3: final polish to deadline.
    if time.process_time() < deadline - 0.2:
        hf, cf = optimize(best, deadline)
        if cf < bestC:
            best, bestC = hf, cf

    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(N)
    return best
